/**
 * Synthetic treemap fixtures for the Storybook coverage set (M3, decision 0055).
 *
 * Three shapes exercise the block end-to-end:
 *  - `bundleModel`   — rollup bundle-analysis tree (bytes / size), a hand-authored
 *                     4-level tree; only leaves carry `value`, containers derive
 *                     their magnitude from descendants (never authored).
 *  - `prChurnModel`  — synthetic file-changes tree (lines / churn); leaves carry
 *                     churn `value` + per-file `{ additions, deletions }` metrics
 *                     for secondary-metric colour and the custom detail slot.
 *  - `diskModel`     — synthetic workspace disk-usage tree (bytes / size),
 *                     with 400 nodes and 10 levels. Folded `"(files)"` leaves
 *                     exercise completeness and deep drilling at ~388 GB scale.
 *
 * Neutral names and seeded synthetic magnitudes retain the coverage shapes,
 * not private repository paths or exact disk measurements.
 *
 * The two large trees are parsed from JSON string literals (not authored as TS
 * object literals) to keep `tsc` fast.
 */
import type { TreemapLens, TreemapModel, TreemapNode } from '../model.ts'

